INSERT INTO `notification_templates` VALUES (1,'BAL_ADD','Balance - Added','Your Account has been Credited',NULL,'<div><div style=\"font-family: Montserrat, sans-serif;\">{{amount}} {{site_currency}} has been added to your account .</div><div style=\"font-family: Montserrat, sans-serif;\"><br></div><div style=\"font-family: Montserrat, sans-serif;\">Transaction Number : {{trx}}</div><div style=\"font-family: Montserrat, sans-serif;\"><br></div><span style=\"color: rgb(33, 37, 41); font-family: Montserrat, sans-serif;\">Your Current Balance is :&nbsp;</span><font style=\"font-family: Montserrat, sans-serif;\"><span style=\"font-weight: bolder;\">{{post_balance}}&nbsp; {{site_currency}}&nbsp;</span></font><br></div><div><font style=\"font-family: Montserrat, sans-serif;\"><span style=\"font-weight: bolder;\"><br></span></font></div><div>Admin note:&nbsp;<span style=\"color: rgb(33, 37, 41); font-size: 12px; font-weight: 600; white-space: nowrap; text-align: var(--bs-body-text-align);\">{{remark}}</span></div>','{{amount}} {{site_currency}} credited in your account. Your Current Balance {{post_balance}} {{site_currency}} . Transaction: #{{trx}}. Admin note is \"{{remark}}\"',NULL,'{\"trx\":\"Transaction number for the action\",\"amount\":\"Amount inserted by the admin\",\"remark\":\"Remark inserted by the admin\",\"post_balance\":\"Balance of the user after this transaction\"}',1,NULL,NULL,0,NULL,0,'2021-11-03 12:00:00','2022-04-03 02:18:28'),(2,'BAL_SUB','Balance - Subtracted','Your Account has been Debited',NULL,'<div style=\"font-family: Montserrat, sans-serif;\">{{amount}} {{site_currency}} has been subtracted from your account .</div><div style=\"font-family: Montserrat, sans-serif;\"><br></div><div style=\"font-family: Montserrat, sans-serif;\">Transaction Number : {{trx}}</div><div style=\"font-family: Montserrat, sans-serif;\"><br></div><span style=\"color: rgb(33, 37, 41); font-family: Montserrat, sans-serif;\">Your Current Balance is :&nbsp;</span><font style=\"font-family: Montserrat, sans-serif;\"><span style=\"font-weight: bolder;\">{{post_balance}}&nbsp; {{site_currency}}</span></font><br><div><font style=\"font-family: Montserrat, sans-serif;\"><span style=\"font-weight: bolder;\"><br></span></font></div><div>Admin Note: {{remark}}</div>','{{amount}} {{site_currency}} debited from your account. Your Current Balance {{post_balance}} {{site_currency}} . Transaction: #{{trx}}. Admin Note is {{remark}}',NULL,'{\"trx\":\"Transaction number for the action\",\"amount\":\"Amount inserted by the admin\",\"remark\":\"Remark inserted by the admin\",\"post_balance\":\"Balance of the user after this transaction\"}',1,NULL,NULL,1,NULL,0,'2021-11-03 12:00:00','2022-04-03 02:24:11'),(7,'PASS_RESET_CODE','Password - Reset - Code','Password Reset',NULL,'<div style=\"font-family: Montserrat, sans-serif;\">We have received a request to reset the password for your account on&nbsp;<span style=\"font-weight: bolder;\">{{time}} .<br></span></div><div style=\"font-family: Montserrat, sans-serif;\">Requested From IP:&nbsp;<span style=\"font-weight: bolder;\">{{ip}}</span>&nbsp;using&nbsp;<span style=\"font-weight: bolder;\">{{browser}}</span>&nbsp;on&nbsp;<span style=\"font-weight: bolder;\">{{operating_system}}&nbsp;</span>.</div><div style=\"font-family: Montserrat, sans-serif;\"><br></div><br style=\"font-family: Montserrat, sans-serif;\"><div style=\"font-family: Montserrat, sans-serif;\"><div>Your account recovery code is:&nbsp;&nbsp;&nbsp;<font size=\"6\"><span style=\"font-weight: bolder;\">{{code}}</span></font></div><div><br></div></div><div style=\"font-family: Montserrat, sans-serif;\"><br></div><div style=\"font-family: Montserrat, sans-serif;\"><font size=\"4\" color=\"#CC0000\">If you do not wish to reset your password, please disregard this message.&nbsp;</font><br></div><div><font size=\"4\" color=\"#CC0000\"><br></font></div>','Your account recovery code is: {{code}}',NULL,'{\"code\":\"Verification code for password reset\",\"ip\":\"IP address of the user\",\"browser\":\"Browser of the user\",\"operating_system\":\"Operating system of the user\",\"time\":\"Time of the request\"}',1,NULL,NULL,0,NULL,0,'2021-11-03 12:00:00','2022-03-20 20:47:05'),(8,'PASS_RESET_DONE','Password - Reset - Confirmation','You have reset your password',NULL,'<p style=\"font-family: Montserrat, sans-serif;\">You have successfully reset your password.</p><p style=\"font-family: Montserrat, sans-serif;\">You changed from&nbsp; IP:&nbsp;<span style=\"font-weight: bolder;\">{{ip}}</span>&nbsp;using&nbsp;<span style=\"font-weight: bolder;\">{{browser}}</span>&nbsp;on&nbsp;<span style=\"font-weight: bolder;\">{{operating_system}}&nbsp;</span>&nbsp;on&nbsp;<span style=\"font-weight: bolder;\">{{time}}</span></p><p style=\"font-family: Montserrat, sans-serif;\"><span style=\"font-weight: bolder;\"><br></span></p><p style=\"font-family: Montserrat, sans-serif;\"><span style=\"font-weight: bolder;\"><font color=\"#ff0000\">If you did not change that, please contact us as soon as possible.</font></span></p>','Your password has been changed successfully',NULL,'{\"ip\":\"IP address of the user\",\"browser\":\"Browser of the user\",\"operating_system\":\"Operating system of the user\",\"time\":\"Time of the request\"}',1,NULL,NULL,1,NULL,0,'2021-11-03 12:00:00','2022-04-05 03:46:35'),(9,'ADMIN_SUPPORT_REPLY','Support - Reply','Reply Support Ticket',NULL,'<div><p><span data-mce-style=\"font-size: 11pt;\" style=\"font-size: 11pt;\"><span style=\"font-weight: bolder;\">A member from our support team has replied to the following ticket:</span></span></p><p><span style=\"font-weight: bolder;\"><span data-mce-style=\"font-size: 11pt;\" style=\"font-size: 11pt;\"><span style=\"font-weight: bolder;\"><br></span></span></span></p><p><span style=\"font-weight: bolder;\">[Ticket#{{ticket_id}}] {{ticket_subject}}<br><br>Click here to reply:&nbsp; {{link}}</span></p><p>----------------------------------------------</p><p>Here is the reply :<br></p><p>{{reply}}<br></p></div><div><br style=\"font-family: Montserrat, sans-serif;\"></div>','Your Ticket#{{ticket_id}} :  {{ticket_subject}} has been replied.',NULL,'{\"ticket_id\":\"ID of the support ticket\",\"ticket_subject\":\"Subject  of the support ticket\",\"reply\":\"Reply made by the admin\",\"link\":\"URL to view the support ticket\"}',1,NULL,NULL,1,NULL,0,'2021-11-03 12:00:00','2022-03-20 20:47:51'),(10,'EVER_CODE','Verification - Email','Please verify your email address',NULL,'<br><div><div style=\"font-family: Montserrat, sans-serif;\">Thanks For joining us.<br></div><div style=\"font-family: Montserrat, sans-serif;\">Please use the below code to verify your email address.<br></div><div style=\"font-family: Montserrat, sans-serif;\"><br></div><div style=\"font-family: Montserrat, sans-serif;\">Your email verification code is:<font size=\"6\"><span style=\"font-weight: bolder;\">&nbsp;{{code}}</span></font></div></div>','---',NULL,'{\"code\":\"Email verification code\"}',1,NULL,NULL,0,NULL,0,'2021-11-03 12:00:00','2022-04-03 02:32:07'),(11,'SVER_CODE','Verification - SMS','Verify Your Mobile Number',NULL,'---','Your phone verification code is: {{code}}',NULL,'{\"code\":\"SMS Verification Code\"}',0,NULL,NULL,1,NULL,0,'2021-11-03 12:00:00','2022-03-20 19:24:37'),(15,'DEFAULT','Default Template','{{subject}}',NULL,'{{message}}','{{message}}',NULL,'{\"subject\":\"Subject\",\"message\":\"Message\"}',1,NULL,NULL,1,NULL,0,'2019-09-14 13:14:22','2021-11-04 09:38:55'),(16,'KYC_APPROVE','KYC Approved','KYC has been approved',NULL,'Your&nbsp;KYC has been approved','Your KYC has been approved',NULL,'[]',1,NULL,NULL,1,NULL,0,NULL,NULL),(17,'KYC_REJECT','KYC Rejected','KYC has been rejected',NULL,'<span style=\"color: rgb(33, 37, 41);\">Your&nbsp;KYC has been&nbsp;</span>rejected<br>','Your KYC has been rejected',NULL,'{\"reason\":\"Rejection Reason\"}',1,NULL,NULL,1,NULL,0,NULL,NULL),(18,'PURCHASE_COMPLETE','Ticket Purchased','Ticket purchased successfully.',NULL,'<div>Your ticket purchase<span style=\"font-weight: bolder;\">&nbsp;</span>has been completed Successfully.<span style=\"font-weight: bolder;\"><br></span></div><div><span style=\"font-weight: bolder;\"><br></span></div><div><span style=\"font-weight: bolder;\">Details of your payment:</span></div><div><span style=\"color: rgb(33, 37, 41);\">Lottery :&nbsp;</span><span style=\"text-align: var(--bs-body-text-align);\"><font color=\"#212529\">{{lottery}}</font></span><br></div><div>Price of lottery : {{price}} {{site_currency}}</div><div>Total Ticket :&nbsp;{{total_ticket}}</div><div>Total Price :&nbsp;{{total_price}}&nbsp;{{site_currency}}</div><div><br></div><div>Transaction Number : {{trx}}</div><div><font size=\"5\"><span style=\"font-weight: bolder;\"><br></span></font></div><div><font size=\"5\">Your current Balance is&nbsp;<span style=\"font-weight: bolder;\">{{post_balance}} {{site_currency}}</span></font></div><div><br style=\"font-family: Montserrat, sans-serif;\"></div>','Your ticket purchase has been completed Successfully.\r\n\r\nDetails of your payment:\r\nLottery : {{lottery}}\r\nPrice of lottery : {{price}} {{site_currency}}\r\nTotal Ticket : {{total_ticket}}\r\nTotal Price : {{total_price}} {{site_currency}}\r\n\r\nTransaction Number : {{trx}}\r\n\r\nYour current Balance is {{post_balance}} {{site_currency}}',NULL,'{\r\n  \"trx\": \"Transaction number\",\r\n  \"lottery\": \"Lottery name\",\r\n  \"price\": \"Ticket price\",\r\n  \"total_ticket\": \"Number of ticket\",\r\n  \"total_price\" : \"Total price\",\r\n  \"post_balance\": \"Balance of the user after this transaction\"\r\n}',1,NULL,NULL,0,NULL,0,'2021-11-03 12:00:00','2023-05-13 11:34:39'),(19,'WINNER','Winning Prize Given','Win the Lottery',NULL,'<div><span style=\"font-weight: bolder;\">Congratulations, you win&nbsp;</span><span style=\"text-align: var(--bs-body-text-align);\"><b>{{lottery}}.</b></span></div><div><span style=\"font-weight: bolder;\"><br></span></div><div><span style=\"font-weight: bolder;\">Details:</span></div><div><span style=\"color: rgb(33, 37, 41);\">Lottery :&nbsp;</span><span style=\"text-align: var(--bs-body-text-align);\"><font color=\"#212529\">{{lottery}}</font></span></div><div>Lottery Result (Normal Balls):&nbsp;{{winning_normal_balls}}</div><div><span style=\"color: rgb(33, 37, 41); font-size: 1rem; text-align: var(--bs-body-text-align);\">Lottery Result (Power Balls)</span>&nbsp;:&nbsp;{{winning_power_balls}}</div><div><br></div><div>You\'ve won {{won_tickets}} tickets</div><div><br></div><div>Your won amount is&nbsp;<span style=\"color: rgb(33, 37, 41); font-size: 1rem; text-align: var(--bs-body-text-align);\">:&nbsp;</span><span style=\"color: rgb(33, 37, 41); font-size: 1rem; text-align: var(--bs-body-text-align); font-weight: bolder;\">{{prize}} {{site_currency}}</span></div><div><br></div><div>Transaction Number : {{trx}}</div><div><br><div><font size=\"5\">Your current Balance is&nbsp;<span style=\"font-weight: bolder;\">{{post_balance}} {{site_currency}}</span></font></div><div><br style=\"font-family: Montserrat, sans-serif;\"></div></div>','Congratulations, you win {{lottery}}.\r\n\r\nDetails:\r\nLottery : {{lottery}}\r\nLottery Result (Normal Balls): {{winning_normal_balls}}\r\nLottery Result (Power Balls) : {{winning_power_balls}}\r\n\r\nYou\'ve won {{won_tickets}} tickets\r\n\r\nYour won amount is Prize : {{prize}} {{site_currency}}\r\n\r\nTransaction Number : {{trx}}\r\n\r\nYour current Balance is {{post_balance}} {{site_currency}}',NULL,'{\r\n  \"trx\": \"Transaction number\",\r\n  \"lottery\": \"Lottery name\",\r\n\"winning_normal_balls\": \"Winning normal ball of the user\",\r\n\"winning_power_balls\": \"Winning power ball of the user\",\r\n  \"prize\": \"Prize money\",\r\n\"won_tickets\" : \"Total winning tickets\",\r\n  \"post_balance\": \"Balance of the user after this transaction\"\r\n}',1,NULL,NULL,0,NULL,0,'2021-11-03 12:00:00','2023-04-10 05:41:03'),(24,'REFERRAL_COMMISSION','Referral Commission','Referral Commission',NULL,'<div style=\"font-family: Montserrat, sans-serif;\">You got&nbsp;<span style=\"font-weight: bolder;\">{{amount}} {{site_currency}}</span>&nbsp;referral commission.</div><div style=\"font-family: Montserrat, sans-serif;\"><span style=\"font-weight: bolder;\"><br></span></div><div style=\"font-family: Montserrat, sans-serif;\"><span style=\"font-weight: bolder;\">Details of your referral commission:</span></div><div style=\"font-family: Montserrat, sans-serif;\">Amount : {{amount}} {{site_currency}}</div><div style=\"font-family: Montserrat, sans-serif;\">{{type}} referral commission</div><div style=\"font-family: Montserrat, sans-serif;\"><span style=\"color: rgb(33, 37, 41);\">Transaction Number : {{trx}}</span><br></div><div style=\"font-family: Montserrat, sans-serif;\">{{level}} level referral commission.</div><div style=\"font-family: Montserrat, sans-serif;\"><font size=\"5\"><span style=\"font-weight: bolder;\"><br></span></font></div><div style=\"font-family: Montserrat, sans-serif;\"><font size=\"5\">Your current Balance is&nbsp;<span style=\"font-weight: bolder;\">{{post_balance}} {{site_currency}}</span></font></div><div style=\"font-family: Montserrat, sans-serif;\"><br></div><div style=\"font-family: Montserrat, sans-serif;\"><br></div>','Your got {{amount}} {{site_currency}} referral commission from {{ref_username}}.',NULL,'{\r\n    \"trx\": \"Transaction number for the interest\",\r\n    \"amount\": \"Amount inserted by the user\",\r\n    \"plan_name\": \"Plan name\",\r\n    \"level\": \"Which level referral commission\",\r\n    \"post_balance\": \"Balance of the user after this transaction\"\r\n}',1,NULL,NULL,1,NULL,0,'2021-11-03 06:00:00','2022-09-21 21:43:49'),(25,'COIN_REQUEST_APPROVED','Coin Request Approved','Coin Request Approved',NULL,'Your coin request was approved just a few times ago.<br><br>Amount:&nbsp;{{amount}} {{site_currency}}<div>Request Time:&nbsp;{{time}},</div><div>Request Number:&nbsp;{{request_number}}<br><div><br></div></div>','Your coin request was approved just a few times ago.',NULL,'{\r\n        \"username\": \"Requested username\",\r\n        \"amount\": \"Requested Amount\",\r\n        \"time\": \"Requested Datetime\",\r\n        \"request_number\": \"Requested system generated number\"\r\n    }',1,NULL,NULL,1,NULL,0,'2021-11-03 06:00:00','2023-10-18 03:36:40'),(26,'WELCOME_BONUS','Welcome Bonus','Welcome Bonus',NULL,'{{username}} welcome to out platform.&nbsp; You have received&nbsp;{{amount}}&nbsp;{{site_currency}} as a signup bonus.','{{username}} welcome to out platform.  You have received {{amount}} {{site_currency}} as a signup bonus.',NULL,'\r\n            {\r\n                \"username\": \"Bonus received username\",\r\n                \"amount\": \"Bonus Amount\"\r\n            }',1,NULL,NULL,1,NULL,0,'2021-11-03 06:00:00','2023-10-18 03:52:06'),(27,'DEPOSIT_COMPLETE','Payment - Automated - Successful','Payment Completed Successfully','{{site_name}} - Payment successful','<div>We\'re delighted to inform you that your payment of {{amount}} {{site_currency}} via {{method_name}} has been completed.</div><div><br></div><div>Below, you\'ll find the details of your payment:</div><div><br></div><div><b>Amount:</b> {{amount}} {{site_currency}}</div><div><b>Charge: </b>{{charge}} {{site_currency}}</div><div><b>Conversion Rate:</b> 1 {{site_currency}} = {{rate}} {{method_currency}}</div><div><b>Received:</b> {{method_amount}} {{method_currency}}</div><div><b>Paid via:</b> {{method_name}}</div><div><b>Transaction Number:</b> {{trx}}</div><div><br></div><div>Your current balance stands at {{post_balance}} {{site_currency}}.</div><div><br></div><div>If you have any questions or need further assistance, feel free to reach out to our support team. We\'re here to assist you in any way we can.</div>','We\'re delighted to inform you that your payment of {{amount}} {{site_currency}} via {{method_name}} has been completed.','Payment Completed Successfully','{\"trx\":\"Transaction number for the payment\",\"amount\":\"Amount inserted by the user\",\"charge\":\"Gateway charge set by the admin\",\"rate\":\"Conversion rate between base currency and method currency\",\"method_name\":\"Name of the payment method\",\"method_currency\":\"Currency of the payment method\",\"method_amount\":\"Amount after conversion between base currency and method currency\",\"post_balance\":\"Balance of the user after this transaction\"}',1,'{{site_name}} Billing',NULL,1,NULL,1,'2021-11-03 12:00:00','2024-05-08 07:20:34'),(28,'DEPOSIT_APPROVE','Payment - Manual - Approved','Payment Request Approved','{{site_name}} - Payment Request Approved','<div>We are pleased to inform you that your payment request of {{amount}} {{site_currency}} via {{method_name}} has been approved.</div><div><br></div><div>Here are the details of your payment:</div><div><br></div><div><b>Amount:</b> {{amount}} {{site_currency}}</div><div><b>Charge: </b>{{charge}} {{site_currency}}</div><div><b>Conversion Rate:</b> 1 {{site_currency}} = {{rate}} {{method_currency}}</div><div><b>Received: </b>{{method_amount}} {{method_currency}}</div><div><b>Paid via: </b>{{method_name}}</div><div><b>Transaction Number: </b>{{trx}}</div><div><br></div><div>Your current balance now stands at {{post_balance}} {{site_currency}}.</div><div><br></div><div>Should you have any questions or require further assistance, please feel free to contact our support team. We\'re here to help.</div>','We are pleased to inform you that your payment request of {{amount}} {{site_currency}} via {{method_name}} has been approved.','Payment of {{amount}} {{site_currency}} via {{method_name}} has been approved.','{\"trx\":\"Transaction number for the payment\",\"amount\":\"Amount inserted by the user\",\"charge\":\"Gateway charge set by the admin\",\"rate\":\"Conversion rate between base currency and method currency\",\"method_name\":\"Name of the payment method\",\"method_currency\":\"Currency of the payment method\",\"method_amount\":\"Amount after conversion between base currency and method currency\",\"post_balance\":\"Balance of the user after this transaction\"}',1,'{{site_name}} Billing',NULL,1,NULL,0,'2021-11-03 12:00:00','2024-05-08 07:19:49'),(29,'DEPOSIT_REJECT','Payment - Manual - Rejected','Payment Request Rejected','{{site_name}} - Payment Request Rejected','<div>We regret to inform you that your payment request of {{amount}} {{site_currency}} via {{method_name}} has been rejected.</div><div><br></div><div>Here are the details of the rejected payment:</div><div><br></div><div><b>Conversion Rate:</b> 1 {{site_currency}} = {{rate}} {{method_currency}}</div><div><b>Received:</b> {{method_amount}} {{method_currency}}</div><div><b>Paid via:</b> {{method_name}}</div><div><b>Charge:</b> {{charge}}</div><div><b>Transaction Number:</b> {{trx}}</div><div><br></div><div>If you have any questions or need further clarification, please don\'t hesitate to contact us. We\'re here to assist you.</div><div><br></div><div>Rejection Reason:</div><div>{{rejection_message}}</div><div><br></div><div>Thank you for your understanding.</div>','We regret to inform you that your payment request of {{amount}} {{site_currency}} via {{method_name}} has been rejected.','Your payment request of {{amount}} {{site_currency}} via {{method_name}} has been rejected.','{\"trx\":\"Transaction number for the payment\",\"amount\":\"Amount inserted by the user\",\"charge\":\"Gateway charge set by the admin\",\"rate\":\"Conversion rate between base currency and method currency\",\"method_name\":\"Name of the payment method\",\"method_currency\":\"Currency of the payment method\",\"method_amount\":\"Amount after conversion between base currency and method currency\",\"rejection_message\":\"Rejection message by the admin\"}',1,'{{site_name}} Billing',NULL,1,NULL,0,'2021-11-03 12:00:00','2024-05-08 07:20:13'),(30,'DEPOSIT_REQUEST','Payment - Manual - Requested','Payment Request Submitted Successfully',NULL,'<div>We are pleased to confirm that your payment request of {{amount}} {{site_currency}} via {{method_name}} has been submitted successfully.</div><div><br></div><div>Below are the details of your payment:</div><div><br></div><div><b>Amount:</b> {{amount}} {{site_currency}}</div><div><b>Charge:</b> {{charge}} {{site_currency}}</div><div><b>Conversion Rate:</b> 1 {{site_currency}} = {{rate}} {{method_currency}}</div><div><b>Payable:</b> {{method_amount}} {{method_currency}}</div><div><b>Pay via: </b>{{method_name}}</div><div><b>Transaction Number:</b> {{trx}}</div><div><br></div><div>Should you have any questions or require further assistance, please feel free to reach out to our support team. We\'re here to assist you.</div>','We are pleased to confirm that your payment request of {{amount}} {{site_currency}} via {{method_name}} has been submitted successfully.','Your payment request of {{amount}} {{site_currency}} via {{method_name}} submitted successfully.','{\"trx\":\"Transaction number for the payment\",\"amount\":\"Amount inserted by the user\",\"charge\":\"Gateway charge set by the admin\",\"rate\":\"Conversion rate between base currency and method currency\",\"method_name\":\"Name of the payment method\",\"method_currency\":\"Currency of the payment method\",\"method_amount\":\"Amount after conversion between base currency and method currency\"}',1,'{{site_name}} Billing',NULL,1,NULL,0,'2021-11-03 12:00:00','2024-04-25 03:27:42'),(31,'WITHDRAW_APPROVE','Withdraw - Approved','Withdrawal Confirmation: Your Request Processed Successfully','{{site_name}} - Withdrawal Request Approved','<div>We are writing to inform you that your withdrawal request of {{amount}} {{site_currency}} via {{method_name}} has been processed successfully.</div><div><br></div><div>Below are the details of your withdrawal:</div><div><br></div><div><b>Amount:</b> {{amount}} {{site_currency}}</div><div><b>Charge:</b> {{charge}} {{site_currency}}</div><div><b>Conversion Rate:</b> 1 {{site_currency}} = {{rate}} {{method_currency}}</div><div><b>You will receive:</b> {{method_amount}} {{method_currency}}</div><div><b>Via:</b> {{method_name}}</div><div><b>Transaction Number:</b> {{trx}}</div><div><br></div><hr><div><br></div><div><b>Details of Processed Payment:</b></div><div>{{admin_details}}</div><div><br></div><div>Should you have any questions or require further assistance, feel free to reach out to our support team. We\'re here to help.</div>','We are writing to inform you that your withdrawal request of {{amount}} {{site_currency}} via {{method_name}} has been processed successfully.','Withdrawal Confirmation: Your Request Processed Successfully','{\"trx\":\"Transaction number for the withdraw\",\"amount\":\"Amount requested by the user\",\"charge\":\"Gateway charge set by the admin\",\"rate\":\"Conversion rate between base currency and method currency\",\"method_name\":\"Name of the withdraw method\",\"method_currency\":\"Currency of the withdraw method\",\"method_amount\":\"Amount after conversion between base currency and method currency\",\"admin_details\":\"Details provided by the admin\"}',1,'{{site_name}} Finance',NULL,1,NULL,0,'2021-11-03 12:00:00','2024-05-08 07:26:37'),(32,'WITHDRAW_REJECT','Withdraw - Rejected','Withdrawal Request Rejected','{{site_name}} - Withdrawal Request Rejected','<div>We regret to inform you that your withdrawal request of {{amount}} {{site_currency}} via {{method_name}} has been rejected.</div><div><br></div><div>Here are the details of your withdrawal:</div><div><br></div><div><b>Amount:</b> {{amount}} {{site_currency}}</div><div><b>Charge:</b> {{charge}} {{site_currency}}</div><div><b>Conversion Rate:</b> 1 {{site_currency}} = {{rate}} {{method_currency}}</div><div><b>Expected Amount:</b> {{method_amount}} {{method_currency}}</div><div><b>Via:</b> {{method_name}}</div><div><b>Transaction Number:</b> {{trx}}</div><div><br></div><hr><div><br></div><div><b>Refund Details:</b></div><div>{{amount}} {{site_currency}} ha